const similarKeptBills = `-- name: SimilarKeptBills :many
SELECT id, user_id, session_id, issuer, kind, amount_cents, currency, invoice_date, due_date, paid_date, payment, repeat, summary, file_name, file_hash, status, reminder_id, created_at, updated_at, standing_id, remind_days_before FROM bills
WHERE user_id = $1 AND status = 'kept' AND amount_cents = $2
  AND (invoice_date IS NOT DISTINCT FROM $3::date
       OR ($4::date IS NOT NULL AND due_date = $4::date)
       OR ($5::date IS NOT NULL AND paid_date = $5::date)
       -- A page without a date of its own (the second page of a bill): the amount is enough.
       OR ($3::date IS NULL AND $4::date IS NULL AND $5::date IS NULL))
ORDER BY id
LIMIT 3
`

type SimilarKeptBillsParams struct {
	UserID      uuid.UUID    `json:"user_id"`
	AmountCents int64        `json:"amount_cents"`
	InvoiceDate sql.NullTime `json:"invoice_date"`
	DueDate     sql.NullTime `json:"due_date"`
	PaidDate    sql.NullTime `json:"paid_date"`
}

// The same bill from another file (a copy, another page): the same amount and one of its dates.
func (q *Queries) SimilarKeptBills(ctx context.Context, arg SimilarKeptBillsParams) ([]Bill, error) {
	rows, err := q.db.QueryContext(ctx, similarKeptBills,
		arg.UserID,
		arg.AmountCents,
		arg.InvoiceDate,
		arg.DueDate,
		arg.PaidDate,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Bill{}
	for rows.Next() {
		var i Bill
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.SessionID,
			&i.Issuer,
			&i.Kind,
			&i.AmountCents,
			&i.Currency,
			&i.InvoiceDate,
			&i.DueDate,
			&i.PaidDate,
			&i.Payment,
			&i.Repeat,
			&i.Summary,
			&i.FileName,
			&i.FileHash,
			&i.Status,
			&i.ReminderID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.StandingID,
			&i.RemindDaysBefore,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

